    try std.testing.expectEqual(engine_module.Chip.scc, engine.current[0].?);
    try std.testing.expectEqual(@as(u8, 0), engine.psg.read(8));
    player.play(230);
    try std.testing.expectEqual(engine_module.Chip.msx, engine.current[0].?);
